import 'package:elara_core/elara_core.dart';
import 'package:test/test.dart';

import '../support.dart';

void main() {
  group('OpenCiclo released model parity', () {
    // Expected values were generated by OpenCiclo 0.2.1 at commit 28f14c3.
    final cases = <(List<int>, double, double, int, double, int)>[
      ([], 30.5, 3.0, 30, 0.5593644180270958, 5),
      ([28], 29.666666666666668, 3.0, 30, 0.563407137917707, 5),
      ([28, 30], 29.75, 2.221347520444482, 30, 0.6754919607793253, 4),
      ([28, 30, 26, 31], 29.5, 2.4426950408889634, 29, 0.6330981969339992, 4),
      (List.filled(8, 28), 28.5, 1.2, 28, 0.8645196993010537, 2),
      (List.filled(8, 22), 23.7, 2.5620652556089896, 24, 0.621702719998765, 4),
      ([15, 50, 24], 26.6, 11.241157484587188, 27, 0.2095614084685088, 18),
    ];
    for (final c in cases) {
      test('upstream point, scale, mode, and probability for ${c.$1}', () {
        final history = historyFor(c.$1);
        final result = OpenCicloEngine().predict(history)!;
        expect(result.modelPoint, closeTo(c.$2, 1e-10));
        expect(result.modelScale, closeTo(c.$3, 1e-10));
        expect(result.predictedLength, c.$4);
        expect(result.predictedDate, day(history.last.startDate, c.$4));
        expect(result.confidence, closeTo(c.$5, 1e-10));
        final probabilities = result.lengthProbabilities!;
        expect(probabilities.length, 90);
        expect(probabilities.values.every((p) => p >= 0 && p <= 1), isTrue);
        expect(probabilities.values.reduce((a, b) => a + b), closeTo(1, 1e-12));
        // Radius encloses the upstream 80% equal-tail interval.
        expect(result.windowDays, c.$6);
      });
    }

    test('uses the released prior even with no completed cycles', () {
      expect(OpenCicloEngine.populationMedian, 30.5);
      expect(OpenCicloEngine.populationMad, 3.0);
      expect(OpenCicloEngine.populationMean, 29.50769230769231);
      expect(OpenCicloEngine.shrinkageK, 2.0);
      expect(OpenCicloEngine().predict([]), isNull);
      expect(OpenCicloEngine().isActive, isTrue);
    });

    test('can condition on a caller-supplied calendar reference date', () {
      final history = historyFor([28, 28, 28]);
      final asOf = day(history.last.startDate, 35);
      final result = OpenCicloEngine(referenceDate: asOf).predict(history)!;
      expect(result.predictedDate, asOf);
      expect(result.lengthProbabilities!.keys.first, 35);
      expect(result.lengthProbabilities!.values.reduce((a, b) => a + b),
          closeTo(1, 1e-12));
    });

    test('uses upstream uniform fallback after the supported range', () {
      final history = historyFor([28, 28]);
      final asOf = day(history.last.startDate, 100);
      final result = OpenCicloEngine(referenceDate: asOf).predict(history)!;
      expect(result.predictedDate, asOf);
      expect(result.lengthProbabilities!.length, 90);
      expect(result.lengthProbabilities!.values.first, closeTo(1 / 90, 1e-12));
    });

    test('normalization remains finite for an extremely long recorded gap', () {
      final result = OpenCicloEngine().predict(historyFor([10000]))!;
      expect(result.predictedLength, 90);
      expect(result.confidence.isFinite, isTrue);
      expect(result.lengthProbabilities!.values.reduce((a, b) => a + b),
          closeTo(1, 1e-12));
    });

    test('rejects duplicate and unsorted period starts', () {
      final first = CycleRecord(startDate: DateTime.utc(2025, 1, 2));
      final before = CycleRecord(startDate: DateTime.utc(2025, 1, 1));
      expect(
          () => OpenCicloEngine().predict([first, first]), throwsArgumentError);
      expect(() => OpenCicloEngine().predict([first, before]),
          throwsArgumentError);
    });
  });
}
